import{_ as a,o,c as t,a2 as r}from"./chunks/framework.BTLSZHNB.js";const m=JSON.parse('{"title":"WorkerBundle — takoform_worker_bundle","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/edge/worker-bundle.md","filePath":"proposals/edge/worker-bundle.md"}'),i={name:"proposals/edge/worker-bundle.md"};function n(s,e,d,l,c,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="workerbundle-—-takoform-worker-bundle" tabindex="-1">WorkerBundle — <code>takoform_worker_bundle</code> <a class="header-anchor" href="#workerbundle-—-takoform-worker-bundle" aria-label="Permalink to &quot;WorkerBundle — `takoform_worker_bundle`&quot;">​</a></h1><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>A build pipeline publishes the exact bytes of one worker build: a main module plus additional ES modules, WASM modules, text, data, and source maps. Worker Versions consume the bundle by name; hosts resolve its bytes through the content-addressed artifact upload API (decision 0012).</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>revision</code>. A bundle is an immutable snapshot: different bytes are a different bundle resource, never an update.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p><code>manifestDigest</code> is the whole desired state: the immutable identity of the artifact manifest committed for this build. That manifest names <code>mainModule</code> and lists every module with its relative path, closed media type, exact size, and canonical sha256 digest; the resource repeats none of it, so the bundle has exactly one source of truth for its bytes and nothing can drift apart from anything. Module linking follows the ES module graph rooted at the main module.</p><p>Before it mutates anything, a host resolves the referenced manifest and holds it to the artifact contract: an uncommitted digest is <code>artifact_missing</code>, and a manifest of another kind, one whose <code>mainModule</code> is not declared, one carrying asset <code>files</code>, one naming a media type outside the closed set, or one overrunning the host&#39;s published bundle limit is <code>artifact_invalid</code>.</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>The bundle is the unit of build identity: digest-pinned bytes plus their linking roles. Any consumer restoring or auditing a version needs exactly this closure.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>A different packaging model — an OCI image, a source tree compiled by the host, or an archive whose bytes are the identity — changes the trust and linking semantics and is a separate Form.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p>None.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None. Bindings belong to <a href="./worker-version.html">WorkerVersion</a>, which binds capabilities to executable snapshots, not to raw bytes.</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>Deleting a bundle still referenced by a Worker Version must fail with <code>dependency_in_use</code>. A host must reject a bundle whose <code>manifestDigest</code> names no committed manifest, or names one the artifact contract refuses (<code>artifact_missing</code> / <code>artifact_invalid</code>), and must keep a referenced manifest and its blobs readable for as long as the bundle exists.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The multi-module worker bundle (main module, additional modules, WASM, source maps) of a proven edge platform, expressed as one verified content-addressed unit per decision 0012.</p>',20)])])}const f=a(i,[["render",n]]);export{m as __pageData,f as default};
